$_SESSION['business_last_seen']=time();$service=new BusinessAccountPortalService(db());$businesses=$service->businesses((int)$account['id']);$claims=$service->claims((int)$account['id']);$applications=$service->applications((int)$account['id']);
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Mi espacio de negocios | Explorando Lugares</title><link rel="stylesheet" href="<?=esc(site_path('/assets/style.css?v=business-portal-2'))?>"><link rel="icon" href="<?=esc(site_path('/assets/favicon.svg'))?>" type="image/svg+xml"></head><body><main class="wrap admin-page account-portal"><a class="brand" href="<?=esc(site_path('/index.html'))?>"><img class="brand-logo" src="<?=esc(site_path('/assets/logo.svg'))?>" alt="" width="64" height="64"><span>Explorando<b>Lugares</b></span></a><div class="account-portal-top"><div><p class="eyebrow">Espacio para negocios</p><h1>Hola, <?=esc($account['display_name'])?></h1><p><?=esc($account['email'])?></p></div><form method="post" action="<?=esc(site_path('/negocios/salir/'))?>"><input type="hidden" name="csrf" value="<?=esc($_SESSION['csrf'])?>"><button class="pill light" type="submit">Cerrar sesión</button></form></div><?php if(($_GET['solicitud']??'')==='recibida'):?><p class="notice" role="status"><strong>Cuenta creada y solicitud recibida.</strong> La revisaremos antes de asociar el negocio o crear una ficha pública.</p><?php endif ?><p class="notice">Tu cuenta solo podrá administrar negocios después de validar la solicitud y autorizar la relación. La cuenta no verifica titularidad ni publica información.</p><section class="destination-admin-list"><h2>Negocios que administras</h2><?php if(!$businesses):?><p>Aún no hay negocios autorizados para administrar.</p><?php else:?><div class="destination-admin-table"><table><thead><tr><th>Negocio</th><th>Destino</th><th>Verificación</th><th>Publicación</th><th>Suscripción</th></tr></thead><tbody><?php foreach($businesses as $business):?><tr><td><?=esc($business['display_name'])?></td><td><?=esc($business['destination_name'])?></td><td><?=esc($business['information_status'])?></td><td><?=esc($business['publication_status'])?></td><td><?=esc($business['plan_code']??'Sin seleccionar')?> · <?=esc($business['subscription_status']??'Pendiente')?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section><section class="destination-admin-list"><h2>Solicitudes asociadas a tu cuenta</h2><?php if(!$applications):?><p>No hay solicitudes registradas.</p><?php else:?><div class="account-application-list"><?php foreach($applications as $application):?><article class="account-application-item"><strong><?=esc($application['business_name'])?></strong><p><?=esc($application['destination_name'])?> · <?=esc($application['category_label'])?> · <?=esc($application['application_type']==='claim_existing'?'Negocio registrado':'Nuevo negocio por validar')?></p><small>Estado: <?=esc(['pending'=>'Pendiente de revisión','in_review'=>'En revisión','not_approved'=>'No aprobada'][$application['status']]??$application['status'])?> · <?=esc($application['created_at'])?></small></article><?php endforeach ?></div><?php endif ?></section><?php if($claims):?><section class="destination-admin-list"><h2>Solicitudes de reclamación anteriores</h2><div class="destination-admin-table"><table><thead><tr><th>Negocio</th><th>Destino</th><th>Estado</th><th>Fecha</th></tr></thead><tbody><?php foreach($claims as $claim):?><tr><td><?=esc($claim['display_name'])?></td><td><?=esc($claim['destination_name'])?></td><td><?=esc($claim['status'])?></td><td><?=esc($claim['created_at'])?></td></tr><?php endforeach ?></tbody></table></div></section><?php endif ?><section class="account-next-steps"><h2>Verificación, suscripción y publicación</h2><p>Después de validar la relación y los datos del negocio, podrás completar su información y elegir una suscripción. Las instrucciones de transferencia, carga del comprobante y revisión de pago todavía están pendientes de implementación.</p></section></main></body></html>
